import { describe, expect, test } from "bun:test";
import { isExpired, type Token } from "./token";

const REFRESH_SKEW_MS = 30_000;

function tokenExpiringIn(ms: number): Token {
  return { value: "t", expiresAt: Date.now() + ms };
}

describe("isExpired", () => {
  test("is not expired well before expiresAt", () => {
    expect(isExpired(tokenExpiringIn(60_000))).toBe(false);
  });

  test("is expired once within 30s of expiresAt", () => {
    expect(isExpired(tokenExpiringIn(REFRESH_SKEW_MS - 1))).toBe(true);
  });

  test("is expired exactly at the 30s skew boundary", () => {
    expect(isExpired(tokenExpiringIn(REFRESH_SKEW_MS))).toBe(true);
  });

  test("is expired at expiresAt", () => {
    expect(isExpired(tokenExpiringIn(0))).toBe(true);
  });

  test("is expired after expiresAt", () => {
    expect(isExpired(tokenExpiringIn(-1_000))).toBe(true);
  });
});

